{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Alpidem, a close structural analogue sharing the same aryl-acetamide core, easily crosses the blood-brain barrier in rat autoradiographic studies with a BUI of 0.71.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Alpidem achieves a brain/plasma ratio of about 2.0-2.5 after systemic administration in rats, directly demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "[18F]-(R)-TRACK, a very close analogue with the same diethylamide and bicyclic heteroaromatic core, passes the BBB and shows high brain uptake in nonhuman primates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "PBR102, another close analogue, shows initial high brain uptake in nonhuman primate PET-CT studies, confirming BBB permeability for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PI1, a related diethylamide-containing compound, is present in good concentrations in rat CSF after intraperitoneal administration, providing direct CNS exposure evidence.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "SRN-003-556, which shares the diethylamide acetamide motif, is BBB-permeant in mice with a brain Cmax of 1.8 µM after oral dosing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental evidence from close structural analogues consistently demonstrates BBB penetration and meaningful CNS access, with no contradictory findings.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule, but multiple close analogues with the same pharmacophore provide consistent direct evidence.",
    "Quantitative unbound brain-to-plasma ratio for the query is not available, but qualitative and semiquantitative CNS exposure is well supported."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

